function chatMainCopy(x){x=x||{};return{base:String(x.base||''),key:String(x.key||''),model:String(x.model||''),streaming:typeof x.streaming==='boolean'?x.streaming:!!(x.base||x.key||x.model)&&typeof S!=='undefined'&&S.settings&&S.settings.chatStreaming===true,temp:x.temp==null?0.8:x.temp,maxTokens:x.maxTokens==null?4096:x.maxTokens,offlineMaxTokens:x.offlineMaxTokens==null?4096:x.offlineMaxTokens,letterMaxTokens:x.letterMaxTokens==null?4096:x.letterMaxTokens,callMaxTokens:x.callMaxTokens==null?4096:x.callMaxTokens,reasoningEnabled:x.reasoningEnabled===true,reasoningEffort:['low','high','max'].includes(x.reasoningEffort)?x.reasoningEffort:'high'};}
