  S=fresh;
  try{mergeBeautyPack(beauty);}catch(_){}// 恢复所有美化字段，避免清空时遗漏壁纸/气泡/图标
  try{initAccounts();}catch(_){}// 账号列表立刻整理好，形象工作室等按钮清空后马上能用
