function showVoicePicker(){const q=(_voiceQ||'').toLowerCase();
  const list=_voiceList.filter(v=>!q||(''+v.id).toLowerCase().indexOf(q)>=0||(''+v.name).toLowerCase().indexOf(q)>=0);
  openModal(`<h3>选个音色（共${_voiceList.length}个）</h3>
    <div class="field"><input id="vp_q" placeholder="搜名字或ID…" value="${esc(_voiceQ)}" oninput="_voiceQ=this.value;showVoicePicker();setTimeout(()=>{var e=document.getElementById('vp_q');if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length);}},0)"></div>
    <div style="max-height:50vh;overflow:auto">${list.slice(0,150).map(v=>`<div class="it" onclick="pickVoice('${esc(v.id)}')" style="cursor:pointer"><span>${v.clone?'<b style="color:#ffb83b">我的克隆 · </b>':''}${esc(v.name)}<br><small style="color:#888">${esc(v.id)}</small></span><span class="v">选</span></div>`).join('')||'<div class="empty" style="padding:20px">没有匹配的</div>'}${list.length>150?'<div class="hint" style="padding:8px">只显示前150个，用搜索找更快</div>':''}</div>
    <button class="btn g" style="margin-top:8px" onclick="closeModal()">关闭</button>`);}
